examples:
import { ContextMenu } from 'moraine'

<ContextMenu>
  <ContextMenu.Trigger>Open</ContextMenu.Trigger>
  <ContextMenu.Content
    items={[{ label: 'Rename' }, { label: 'Share', children: [{ label: 'Copy link' }] }]}
    itemRender={(props) => (
      <span>
        {props.item.label}
        {props.hasChildren ? ' ›' : ''}
      </span>
    )}
  />
</ContextMenu>

